{
  "name": "todo-cli",
  "version": "0.3.0",
  "description": "A tiny to-do list for the command line.",
  "type": "module",
  "bin": {
    "todo": "src/index.js"
  },
  "scripts": {
    "start": "node src/index.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

export function formatTodo(todo, index) {
  const box = todo.done ? '[x]' : '[ ]';
  return `${String(index + 1).padStart(2)}. ${box} ${todo.text}`;
}

export function formatList(todos) {
  if (todos.length === 0) return 'Nothing to do. Add one with: todo add "..."';
  return todos.map(formatTodo).join('\n');
}

export function formatSummary(todos) {
  const open = todos.filter((todo) => !todo.done).length;
  const word = open === 1 ? 'to-do' : 'to-dos';
  return `${open} open ${word}, ${todos.length - open} done.`;
}

#!/usr/bin/env node
import { formatList, formatSummary } from './format.js';
import { addTodo, completeTodo, loadTodos, removeTodo } from './store.js';

const file = process.env.TODO_FILE ?? 'todos.json';
const [command, ...rest] = process.argv.slice(2);

function readNumber(value) {
  const number = Number(value);
  if (!Number.isInteger(number) || number < 1) {
    throw new Error(`"${value}" is not a to-do number. Run "todo list" to see the numbers.`);
  }
  return number;
}

async function main() {
  switch (command) {
    case 'add': {
      const text = rest.join(' ').trim();
      if (!text) throw new Error('Say what to add: todo add "Buy oat milk"');
      const todo = await addTodo(file, text);
      console.log(`Added: ${todo.text}`);
      break;
    }
    case 'list': {
      const todos = await loadTodos(file);
      console.log(formatList(todos));
      console.log(formatSummary(todos));
      break;
    }
    case 'done': {
      const todo = await completeTodo(file, readNumber(rest[0]));
      console.log(`Done: ${todo.text}`);
      break;
    }
    case 'remove': {
      const todo = await removeTodo(file, readNumber(rest[0]));
      console.log(`Removed: ${todo.text}`);
      break;
    }
    default:
      console.log('Usage: todo <add|list|done|remove> [text or number]');
      process.exitCode = command ? 1 : 0;
  }
}

main().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});

import { readFile, writeFile } from 'node:fs/promises';

export async function loadTodos(file) {
  try {
    const text = await readFile(file, 'utf8');
    return JSON.parse(text);
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

export async function saveTodos(file, todos) {
  await writeFile(file, `${JSON.stringify(todos, null, 2)}\n`);
}

export async function addTodo(file, text) {
  const todos = await loadTodos(file);
  const todo = { text, done: false, added: new Date().toISOString().slice(0, 10) };
  todos.push(todo);
  await saveTodos(file, todos);
  return todo;
}

function pick(todos, number) {
  const todo = todos[number - 1];
  if (!todo) throw new Error(`There is no to-do number ${number}.`);
  return todo;
}

export async function completeTodo(file, number) {
  const todos = await loadTodos(file);
  const todo = pick(todos, number);
  todo.done = true;
  await saveTodos(file, todos);
  return todo;
}

export async function removeTodo(file, number) {
  const todos = await loadTodos(file);
  pick(todos, number);
  const [removed] = todos.splice(number - 1, 1);
  await saveTodos(file, todos);
  return removed;
}

import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { test } from 'node:test';
import { addTodo, completeTodo, loadTodos, removeTodo } from '../src/store.js';

async function withFile(run) {
  const dir = await mkdtemp(join(tmpdir(), 'todo-cli-'));
  try {
    await run(join(dir, 'todos.json'));
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

test('a missing file is an empty list', () =>
  withFile(async (file) => {
    assert.deepEqual(await loadTodos(file), []);
  }));

test('add keeps to-dos in the order they were added', () =>
  withFile(async (file) => {
    await addTodo(file, 'Buy oat milk');
    await addTodo(file, 'Call the plumber');
    const todos = await loadTodos(file);
    assert.deepEqual(
      todos.map((todo) => todo.text),
      ['Buy oat milk', 'Call the plumber'],
    );
  }));

test('done marks the numbered to-do and saves it', () =>
  withFile(async (file) => {
    await addTodo(file, 'Buy oat milk');
    await addTodo(file, 'Call the plumber');
    await completeTodo(file, 2);
    const todos = await loadTodos(file);
    assert.equal(todos[0].done, false);
    assert.equal(todos[1].done, true);
  }));

test('remove takes out the numbered to-do', () =>
  withFile(async (file) => {
    await addTodo(file, 'Buy oat milk');
    await addTodo(file, 'Call the plumber');
    await addTodo(file, 'Water the plants');
    const removed = await removeTodo(file, 1);
    assert.equal(removed.text, 'Buy oat milk');
    const todos = await loadTodos(file);
    assert.deepEqual(
      todos.map((todo) => todo.text),
      ['Call the plumber', 'Water the plants'],
    );
  }));

test('a number past the end is an error', () =>
  withFile(async (file) => {
    await addTodo(file, 'Buy oat milk');
    await assert.rejects(removeTodo(file, 3), /no to-do number 3/);
  }));
